<script setup lang="ts">
import {onMounted,ref} from 'vue'
import {request,demoMode} from '@/services/quality'
import AppModal from '@/components/AppModal.vue'
interface InternalUser {id:number;name:string;email:string;is_support_staff:boolean;is_support_coordinator:boolean;internal_active:boolean;internal_version:number}
const users=ref<InternalUser[]>([]);const invitations=ref<{id:number;email:string;expires_at:string;accepted_at:string|null}[]>([]);const error=ref('');const notice=ref('');const open=ref(false);const busy=ref(false);const selected=ref<InternalUser|null>(null);const email=ref('');const staff=ref(true);const coordinator=ref(false);const reason=ref('')
async function load(){try{const d=await request<{users:InternalUser[];invitations:typeof invitations.value}>('/platform/internal-team');users.value=d.users;invitations.value=d.invitations}catch(e){error.value=(e as Error).message}}
function edit(u:InternalUser|null){selected.value=u;email.value='';reason.value='';error.value='';open.value=true}
async function save(){busy.value=true;error.value='';try{if(selected.value)await request('/platform/internal-team/'+selected.value.id,'PUT',{internal_active:!selected.value.internal_active,version:selected.value.internal_version,reason:reason.value});else await request('/platform/internal-team/invitations','POST',{email:email.value,staff:staff.value,coordinator:coordinator.value});open.value=false;notice.value='Opération enregistrée. Les invitations restent en attente d’acceptation et leur livraison est suivie dans Notifications.';await load()}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
onMounted(()=>{if(!demoMode)load()})
</script>
<template><section class="page erp-page"><div class="page-heading compact"><div><p class="eyebrow">ENTREPRISE EXPLOITANTE</p><h1>Équipe d’accompagnement</h1><p class="page-subtitle">Un rôle interne ne crée pas d’accès métier aux officines.</p></div><button v-if="!demoMode" class="button primary" @click="edit(null)">Inviter un collaborateur</button></div><p v-if="demoMode" class="panel form-body">Disponible dans l’aperçu API.</p><p v-if="error&&!open" class="alert error" role="alert">{{error}}</p><p v-if="notice" class="alert success" role="status">{{notice}}</p><div class="panel"><div class="table-scroll"><table><thead><tr><th>COLLABORATEUR</th><th>RÔLES INTERNES</th><th>ÉTAT</th><th>ACTION</th></tr></thead><tbody><tr v-for="u in users" :key="u.id"><td>{{u.name}}<span class="table-subtitle">{{u.email}}</span></td><td>{{u.is_support_staff?'Accompagnateur ':''}}{{u.is_support_coordinator?'Coordinateur':''}}</td><td>{{u.internal_active?'Actif':'Désactivé'}}</td><td><button class="button secondary small" @click="edit(u)">{{u.internal_active?'Désactiver':'Réactiver'}}</button></td></tr></tbody></table></div></div><div class="panel overview-recent"><div class="panel-heading"><h2>Invitations internes</h2></div><div class="form-body"><p v-for="i in invitations" :key="i.id" class="page-subtitle">{{i.email}} · {{i.accepted_at?'Acceptée':'En attente ou expirée'}} · expiration {{i.expires_at}} UTC</p><p v-if="!invitations.length" class="empty-state">Aucune invitation.</p></div></div><AppModal v-model="open" :title="selected?'Modifier l’accès interne':'Inviter un collaborateur'" :busy="busy"><form id="internal-team" class="form-body correction-form" @submit.prevent="save"><p v-if="error" class="alert error" role="alert">{{error}}</p><template v-if="!selected"><label>Email destinataire<input v-model="email" type="email" required maxlength="254"/></label><label class="checkbox-label"><input v-model="staff" type="checkbox"/>Accompagnateur éligible</label><label class="checkbox-label"><input v-model="coordinator" type="checkbox"/>Coordinateur (métadonnées et propositions, sans données métier)</label></template><template v-else><p>{{selected.name}} · le compte personnel et les autres appartenances seront conservés.</p><label>Motif obligatoire<textarea v-model="reason" rows="4" required maxlength="2000"/></label></template></form><template #footer><button class="button secondary" :disabled="busy" @click="open=false">Annuler</button><button class="button primary" :disabled="busy||(!selected&&!staff&&!coordinator)" type="submit" form="internal-team">Confirmer</button></template></AppModal></section></template>
